  explain=[
      "Una vuelta completa mide 360°. Si se reparte en partes iguales, cada ángulo mide 360° dividido por el número de partes. En 4 partes cada ángulo es recto, porque 360 ÷ 4 = 90.",
      "Con 6 partes iguales cada ángulo mide 60°, con 8 partes mide 45° y con 12 partes mide 30°, como entre dos números del reloj. Todos son agudos, porque miden menos de 90°. Con 2 partes se obtiene el ángulo extendido de 180°.",
      "Cuando se juntan ángulos seguidos con el mismo vértice, se suman sus medidas. Si el total es 90° es recto, si está entre 90° y 180° es obtuso, si es 180° es extendido y si es 360° es completo.",
  ],
  vocab=[("giro", "movimiento de rotación alrededor de un punto"), ("partes iguales", "porciones que miden lo mismo"), ("ángulos seguidos", "ángulos que comparten el vértice y un lado"), ("clasificar", "poner un nombre según la medida")],
  worked=[
      ("Repartir la vuelta", "Un círculo se divide en 5 partes iguales con líneas desde el centro. ¿Cuánto mide cada ángulo y de qué tipo es?", ["Se divide la vuelta completa: 360 ÷ 5 = 72.", "72° es menor que 90°."], "72°, agudo"),
      ("Sumar ángulos seguidos", "Tres ángulos seguidos miden 40°, 55° y 70°. ¿Cuánto mide el ángulo total y de qué tipo es?", ["40 + 55 + 70 = 165.", "165° está entre 90° y 180°."], "165°, obtuso"),
  ],
  mist=[
      ("Dividir 180° en vez de 360° al repartir una vuelta completa.", "Una vuelta completa mide 360°, no 180°.", "Parte siempre de 360° si se reparte toda la vuelta."),
      ("Llamar agudo a un ángulo de 165°.", "165° es mayor que 90°.", "Compara con 90° antes de clasificar."),
  ],
  R=[arith("Una vuelta se reparte en 4 partes iguales. ¿Cuántos grados mide cada una?", "360//4", "Se divide 360° en 4 partes.", "°"),
     arith("Una vuelta se reparte en 12 partes iguales, como un reloj. ¿Cuántos grados mide cada parte?", "360//12", "Se divide 360° en 12 partes.", "°"),
     ex("¿Cuántos grados mide media vuelta?", "180", "Es la mitad de 360°.", calc="360//2")],
  C=[ex("Un ángulo de 60° se repite 6 veces alrededor de un punto. ¿Cuántos grados cubren en total?", "360", "6 × 60° = 360°, una vuelta completa.", calc="6*60"),
     ex("Dos ángulos seguidos miden 80° y 60°. ¿De qué tipo es el ángulo total?", "Obtuso", "80 + 60 = 140°, que está entre 90° y 180°."),
     ex("Una rueda tiene 8 rayos que forman ángulos iguales en el centro. ¿Cuánto mide cada ángulo entre rayos seguidos?", "45°", "360 ÷ 8 = 45.", calc="360//8")],
